function render() {
  background(240, 245, 250);

  if (gameState === 'PLAYING' || gameState === 'GAMEOVER') {
    fill(220, 225, 230);
    noStroke();
    textSize(150);
    textAlign(CENTER, CENTER);
    text(score, width / 2, height / 2);
  }

  for (let p of pipes) {
    let hw = HOOP_WIDTH;
    let hh = 15;

    stroke(200);
    strokeWeight(1);
    fill(255, 255, 255, 180);
    beginShape();
    vertex(p.x, p.y);
    vertex(p.x + 10, p.y + 40);
    vertex(p.x + hw - 10, p.y + 40);
    vertex(p.x + hw, p.y);
    endShape(CLOSE);

    stroke(220);
    for(let i = 1; i <= 3; i++) {
      let topX = p.x + i * hw/4;
      let botX = p.x + 10 + i * (hw-20)/4;
      line(topX, p.y, botX, p.y + 40);
      line(p.x + i * hw/4, p.y, p.x + 10 + (i-1) * (hw-20)/4, p.y + 40);
      line(p.x + (i-1) * hw/4, p.y, p.x + 10 + i * (hw-20)/4, p.y + 40);
    }

    stroke(220, 50, 0);
    noFill();
    strokeWeight(4);
    arc(p.x + hw/2, p.y, hw, hh, PI, TWO_PI);
  }

  push();
  translate(bird.x, bird.y);
  rotate(frames * 0.05);

  fill(255, 140, 0);
  noStroke();
  circle(0, 0, bird.size);

  stroke(50);
  strokeWeight(1.5);
  noFill();

  arc(-bird.size/4, 0, bird.size/2, bird.size, -PI/2, PI/2);
  arc(bird.size/4, 0, bird.size/2, bird.size, PI/2, 3*PI/2);
  line(0, -bird.size/2, 0, bird.size/2);
  line(-bird.size/2, 0, bird.size/2, 0);
  pop();

  for (let p of pipes) {
    let hw = HOOP_WIDTH;
    let hh = 15;

    stroke(255, 80, 0);
    noFill();
    strokeWeight(4);
    arc(p.x + hw/2, p.y, hw, hh, 0, PI);

    fill(255, 80, 0);
    noStroke();
    circle(p.x, p.y, 4);
    circle(p.x + hw, p.y, 4);
  }

  if (gameState === 'GAMEOVER') {
    fill(0, 150);
    rectMode(CORNER);
    rect(0, 0, width, height);

    fill(255);
    noStroke();
    textSize(40);
    textAlign(CENTER, CENTER);
    text("GAME OVER", width / 2, height / 2 - 20);
    textSize(20);
    text("Score: " + score, width / 2, height / 2 + 30);
    text("Press SPACE to Restart", width / 2, height / 2 + 70);
  }
}
```

